import{_ as t,o,c as s,a2 as r}from"./chunks/framework.BsgK4TUM.js";const d=JSON.parse('{"title":"Memberships","description":"","frontmatter":{},"headers":[],"relativePath":"how-tos/memberships.md","filePath":"how-tos/memberships.md"}'),i={name:"how-tos/memberships.md"};function n(a,e,l,c,h,p){return o(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="memberships" tabindex="-1">Memberships <a class="header-anchor" href="#memberships" aria-label="Permalink to &quot;Memberships&quot;">​</a></h1><p>Memberships and protected access to content is managed through Concrete CMS&#39;s users, user groups and permission systems.</p><p>Community Store allows products to be flagged to create a user account on purchase (if not already logged in), adding the user to one or more user groups. Such configuration is performed on the &#39;Downloads and User Groups&#39; tab when editing products.</p><p>For example, you may wish to set up a website to sell access to a protected set of pages and resources. To do this, you would configure the following in your site:</p><ul><li>Create a new User Group, through the <strong>Members / User Groups</strong> Dashboard page, e.g. &#39;12 Months membership&#39;</li><li>Configure the new user group to <strong>Automatically remove users from this group</strong> after 365 days, removing the user from the group on expiration</li><li>Create a membership product, e.g. &#39;12 Month Access to Resources&#39;, and configure the product: <ul><li>set <strong>Product is Shippable</strong> to no</li><li>set <strong>Offer quantity selection</strong> to no</li><li>set the <strong>Stock Level</strong> to unlimited</li><li>check the <strong>Create user account on purchase</strong> option</li><li>select the newly created user group within the list <strong>On purchase add user to user groups</strong></li><li>you may also wish to set the <strong>Send customer directly to checkout when added to cart</strong> option to streamline the checkout process</li><li>finally, you may wish to set the <strong>Prevent this item from being in the cart with other items</strong> option if you are offering multiple levels of membership and do not wish users to buy multiple at once</li></ul></li><li>Set permissions on your site at the page level, allowing only the membership user group to view those pages</li></ul><p>With the configuration above, when a customer places and pays for an order including the membership product, they will receive an additional email with new login credentials and a link to log into the site. If supported by the payment gateway (i.e. it is not processed externally), the user will be logged in automatically after completing the transaction. As the new user has been placed in a user group that automatically expires, they will be limited to 365 days worth of access to the protected resources.</p><div class="tip custom-block"><p class="custom-block-title">Advanced Permissions</p><p>Concrete&#39;s <a href="https://documentation.concretecms.org/user-guide/editors-reference/dashboard/system-and-maintenance/permissions-and-access/advanced-permissions" target="_blank" rel="noreferrer">advanced permissions system</a> is well suited to this setup and gives a high level of control over content. For example, using advanced permissions individual blocks of content can be placed on the site, only visible to users within selected user groups. A content block directly highlighting and linking the newly accessible content could be placed on the page members log in to, being configured to only be visible to users within the membership group.</p></div>',7)])])}const m=t(i,[["render",n]]);export{d as __pageData,m as default};
